__NUXT_JSONP__("/svet/stat/rovnikova-guinea/retezce", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p){return {data:[{tabsLoad:{tabWhatToSee:c,tabPrice:c,tabPeople:c,tabTrip:c,tabContact:c,tabHotel:c,tabNeighboring:h,tabVideos:d,tabArticles:d,tabWallSockets:h,tabChains:d,tabFauna:d,tabFlora:d,tabFoods:d,tabBrands:d},place:[{tld:".gq",name:"Rovníková Guinea",area:28051,population:1402985,slug:k,id_continent:f,information_chatgpt:"\u003Cp\u003ERovníková Guinea je africký stát, který se nachází na západním pobřeží Afriky. Je to jeden z nejmenších států v Africe, ale má obrovský potenciál pro rozvoj díky svým přírodním zdrojům, jako jsou ropa, zemní plyn a dřevo.\u003C\u002Fp\u003E\n\u003Cp\u003ETento stát má bohatou a rozmanitou kulturu, kterou ovlivnily místní kmeny, kolonizace a modernizace. Návštěvníci se mohou těšit na tradiční tance, zpěvy, řemesla a kuchyni. Kromě toho je Rovníková Guinea proslulá svými plážemi, ostrovy, přírodními parky a vodopády.\u003C\u002Fp\u003E\n\u003Cp\u003EJedním z největších turistických lákadel v Rovníkové Guineji je ostrov Bioko. Tento ostrov je známý pro své nádherné pláže, turistické trasy a přírodní rezervace. Návštěvníci se zde mohou potápět v korálových útesech, rybařit, pozorovat ptáky a procházet se v deštném pralese. Kromě toho je Bioko domovem kriticky ohroženého opice Drill.\u003C\u002Fp\u003E\n\u003Cp\u003EV hlavním městě Malabo se nachází několik památek, jako jsou katedrála svatého Izidora, palác prezidenta a muzeum, které zachycuje historii státu. Malabo je také výchozím bodem pro cestování do přírodních parků, jako je park Monte Alen a park Uoro.\u003C\u002Fp\u003E\n\u003Cp\u003ERovníková Guinea se v posledních letech stala stále oblíbenějším turistickým cílem. Nabízí mnoho příležitostí pro dobrodružství, poznání kultury a odpočinek. Je to fascinující a krásný kousek Afriky, který stojí za návštěvu.\u003C\u002Fp\u003E",currency_code:"XAF",currency_name:"rovníkovoguinejský frank",money_prices:[{name:"Taxi (cena za km)",value:l,date_update:b},{name:"Hlavní jídlo",value:5000,date_update:b},{name:"Chleba",value:300,date_update:b},{name:"Mléko",value:1500,date_update:b},{name:"Voda (500ml)",value:m,date_update:b},{name:"Espresso",value:n,date_update:b},{name:"Zmrzlina (jeden kopeček)",value:m,date_update:b},{name:"Pivo",value:l,date_update:b},{name:"Krabička cigaret",value:a,date_update:b},{name:"Bic Mac",value:a,date_update:b},{name:"Coca Cola (500ml)",value:n,date_update:b}],phone_numbers_emergency:[{name:"Mezinárodní tísňová linka",value:"112",date_update:g},{name:"Policie",value:"240 222 206",date_update:g},{name:"Hasiči",value:"116",date_update:g},{name:"Zdravotnická záchranná služba",value:"115",date_update:g}],phone_prefix:"+240",coordinates:[{latitude:"1.6508",longitude:"10.2679"}],people_religion:[{name:"Křesťanství",value:"93 %"},{name:"Domorodá náboženství",value:"5 %"},{name:"Islám",value:"2 %"},{name:"Judaismus",value:i},{name:"Hinduismus",value:i},{name:"Bahaismus",value:i}],people_nationality:a,visitors_entry:[{name:"Občanský průkaz",value:"Pro vstup do Rovníkové Guiney je potřeba cestovat s platným cestovním pasem, občanský průkaz není dostačující.",date_update:e},{name:"Cestovní pas",value:"Pro vstup do Rovníkové Guiney je nezbytné mít platný cestovní pas.",date_update:e},{name:"Vízum",value:"Pro vstup do Rovníkové Guiney je pro občany české republiky nezbytné získat vízum před cestou. Podrobné informace lze získat na stránkách velvyslanectví Rovníkové Guiney.",date_update:e},{name:"Očkování",value:"Pro vstup do Rovníkové Guiney není vyžadováno žádné specifické očkování. Nicméně, doporučuje se vakcinace proti žluté zimnici a dalším běžným infekčním chorobám.",date_update:e},{name:"Cestovní pojištění",value:"Při vstupu do Rovníkové Guiney není vyžadováno mít cestovní nebo zdravotní pojištění. Nicméně, doporučuje se mít platné pojištění, aby se zajistila péče v případě zdravotních problémů během pobytu v zemi.",date_update:e},{name:"Bezpečnostní situace",value:"Rovníková Guinea je považována za zemi s vysokou mírou kriminality a korupce. Z tohoto důvodu je důležité být opatrný a dbát na bezpečnostní opatření, jako je například používání bezpečnostního doprovodu a vyhýbání se nočním výletům.",date_update:e},{name:"Další informace",value:"V Rovníkové Guineji je vysoká úroveň chudoby a mnoho míst nemá základní infrastrukturu. Turisté by měli být připraveni na to, že cestování po zemi může být náročné a vyžaduje si plánování a pečlivé zvažování. Kromě toho se v zemi setkáte s mnoha různými kulturami a zvyklostmi, a proto je vhodné mít otevřenou mysl a respektovat místní tradice a obyčeje.",date_update:e}],type_place:o,id_image_cover:j,id_image_hero:j,id_city_main:849,affiliate:[{name:"booking",value:c}],mpz:"GQ",alerts:a,zoom:[{google:p,booking:p}],ids_neighboring_countries:[{id:47},{id:76}],organization:a,apps:a,links:a,information_author:a,seo_tags:a,language_phrases:a,wall_sockets:a,id:88,facts_place:a,created_at:"2023-12-27T16:33:10.517062+00:00",updated_at:"2023-12-27T17:07:31.480426+00:00",name_original:a}],imagePlace:[{id:j,name:k,source:"\u002Fworld\u002Fstates\u002F",type:o,author:"pixabay.com",created_at:"2023-05-03T20:14:00.749527+00:00",updated_at:"2023-12-27T20:42:18.520959+00:00"}],placeContinent:[{id:f,slug:"afrika",name:"Afrika",area:30370000,population:1340000000,population_density:44.12,number_states:54,information_chatgpt:"\u003Cp\u003EAfrika je největší kontinent na Zemi a rozkládá se na ploše přesahující 30 milionů kilometrů čtverečních. Nachází se zde více než 50 zemí a žije zde více než 1,3 miliardy lidí. \u003C\u002Fp\u003E\n\u003Cp\u003EJižní Afrika, Egypt, Maroko a Keňa patří mezi nejoblíbenější turistické cíle v Africe. V Jihoafrické republice se můžete podívat na slavné Krugerův národní park a sledovat zde život zvířat v jejich přirozeném prostředí. Egypt je zase proslulý svými pyramidami, které se nacházejí v Gíze. V Maroku můžete navštívit tradiční trhy, zatímco v Keni se můžete setkat s Masajským kmenem a podívat se na úžasnou přírodu.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má bohatou historii a kulturu. První lidé, kteří se usadili v Africe, byli loveckým a sběračským národem. Poté se v této oblasti objevily první civilizace, jako je Kúšská říše, Egyptská říše nebo Království Aksum. Afrika byla také kolonizována evropskými mocnostmi a toto období mělo značný dopad na dnešní politickou situaci na kontinentu.\u003C\u002Fp\u003E\n\u003Cp\u003EJe důležité zmínit, že Afrika má velké množství jazyků a kultur. Zahrnuje mnoho různých národů a etnických skupin, a to má vliv na různorodost obyvatelstva a kultury. Nejrozšířenějším jazykem je arabština, která se mluví především v severní Africe a v některých částech západní Afriky. Dalšími důležitými jazyky jsou svahilština, francouzština, portugalština, angličtina a mnoho dalších.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika má také nádhernou přírodu. Nachází se zde nejvyšší hora světa, Kilimandžáro, která se nachází na území Tanzanie a Keňy. Kromě toho se v Africe nachází také největší pouště na světě, Sahara, a největší prales, Kongský prales. Na tomto kontinentě můžete vidět také mnoho zvířat, jako jsou sloni, lvi, gepardi, zebry a mnoho dalších druhů. V Africe se také nachází několik nejvýznamnějších řek světa, jako je Nil, Kongo, Niger a Zambezi.\u003C\u002Fp\u003E\u003Cp\u003EAfrika je bohužel také známá pro své problémy. Mnoho zemí se potýká s chudobou, nedostatkem potravin a vody, nemocemi a válečnými konflikty. Mnoho afrických zemí závisí na zemědělství a rybolovu, což však často není dostatečně výnosné, aby zabezpečilo potřeby obyvatelstva. Kromě toho jsou některé země v Africe trvale postižené extrémními přírodními katastrofami, jako jsou sucha, povodně a bouře.\u003C\u002Fp\u003E\n\u003Cp\u003ENa druhou stranu se v Africe také nachází mnoho lidí, kteří se snaží změnit situaci a zlepšit životy svých spoluobčanů. Vznikají neziskové organizace, které se snaží pomáhat při řešení těchto problémů a zlepšovat kvalitu života v mnoha afrických zemích. Zároveň se v posledních letech objevují nové možnosti pro ekonomický růst a rozvoj, jako jsou technologické start-upy a zahraniční investice.\u003C\u002Fp\u003E\n\u003Cp\u003EAfrika je fascinující kontinent, který nabízí mnoho zážitků a zároveň v sobě ukrývá mnoho výzev. Pokud se rozhodnete navštívit Afriku, můžete se těšit na krásnou přírodu, bohatou kulturu a nezapomenutelné zážitky. Je však také důležité být obezřetný a připravený na místní podmínky, protože některé oblasti mohou být nebezpečné kvůli konfliktům nebo zločinnosti.\u003C\u002Fp\u003E",coordinates:[{latitude:1.650801,longitude:17.371642}],type_place:"continent",id_image_cover:f,id_image_hero:f,zoom:[{google:h,booking:3}],information_author:a,seo_tags:a,created_at:"2023-12-27T16:35:37.460505+00:00",updated_at:"2023-12-27T17:07:06.531847+00:00",name_original:a}]}],fetch:{"OrganismsoSidebarListComponent:0":{events:[],images:a}},mutations:[]}}(null,"01-2021",true,0,"05-2023",5,"09-2021",2,"\u003C 1 %",346,"rovnikova-guinea",2000,500,1000,"state",8)));